// Validate the contact and turn the configured steps into queue rows.
const s = $input.first().json;
const email = String(s.email || '').trim().toLowerCase();
const firstName = String(s.first_name || '').trim() || 'there';
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
  return [{ json: { valid: false, error: 'A valid "email" field is required in the request body.' } }];
}
const steps = Array.isArray(s.steps) ? s.steps : [];
if (!steps.length) return [{ json: { valid: false, error: 'Sequence Settings has no steps configured.' } }];
const fill = (t) => String(t || '').replaceAll('{first_name}', firstName);
const now = Date.now();
const rows = steps.map((st, i) => ({
  email,
  first_name: firstName,
  sequence_name: s.sequence_name,
  step: i + 1,
  subject: fill(st.subject),
  body: fill(st.body),
  send_at: new Date(now + Number(st.delay_hours || 0) * 3600 * 1000).toISOString(),
  from_email: s.from_email,
  max_attempts: Number(s.max_attempts) || 3,
  retry_minutes: Number(s.retry_minutes) || 30,
}));
return [{ json: { valid: true, email, sequence_name: s.sequence_name, rows } }];
